import { Options, Replies } from 'amqplib';

interface QueueClientConfig {
    /**
     * RabbitMQ connection URL.
     *
     * Example:
     * amqp://guest:guest@localhost:5672
     */
    readonly url: string;
    /**
     * Name displayed in the RabbitMQ Management UI.
     */
    readonly connectionName?: string;
    /**
     * Heartbeat interval in seconds.
     */
    readonly heartbeat?: number;
    /**
     * Maximum reconnect attempts.
     *
     * Undefined means retry forever.
     */
    readonly maxReconnectAttempts?: number;
    /**
     * Initial reconnect delay in milliseconds.
     *
     * @default 1000
     */
    readonly reconnectDelay?: number;
    /**
     * Maximum reconnect delay in milliseconds.
     *
     * @default 30000
     */
    readonly maxReconnectDelay?: number;
    /**
     * Automatically recreate queues after reconnect.
     *
     * @default true
     */
    readonly autoRecover?: boolean;
}

type QueueRetryBackoffType = "FIXED" | "EXPONENTIAL";
interface QueueBackoffPolicy {
    readonly type: QueueRetryBackoffType;
    readonly delayMs: number;
    readonly maxDelayMs?: number;
}
interface QueueRetryPolicy {
    /**
     * Number of retries after the initial
     * message delivery.
     *
     * For example, maxRetries: 10 means
     * the message may be delivered a total
     * of 11 times:
     *
     * initial delivery + 10 retries.
     */
    readonly maxRetries: number;
    readonly backoff: QueueBackoffPolicy;
}
interface QueueSubscribeOptions extends Options.Consume {
    /**
     * Retry policy for failed message
     * processing.
     *
     * When omitted, the default policy is used.
     */
    readonly retry?: QueueRetryPolicy;
}

declare enum QueueClientState {
    DISCONNECTED = "DISCONNECTED",
    CONNECTING = "CONNECTING",
    CONNECTED = "CONNECTED",
    RECONNECTING = "RECONNECTING",
    CLOSED = "CLOSED"
}

declare class QueueClient {
    private readonly config;
    private connectionManager;
    private readonly queues;
    private state;
    constructor(config: QueueClientConfig);
    get connected(): boolean;
    get currentState(): QueueClientState;
    connect(): Promise<void>;
    publish<T>(queueName: string, message: T, options?: Options.Publish): Promise<boolean>;
    subscribe<T>(queueName: string, handler: (message: T) => Promise<void> | void, options?: QueueSubscribeOptions): Promise<Replies.Consume>;
    close(): Promise<void>;
    private getQueue;
    private registerConnectionHandlers;
    private reconnect;
}

declare function createQueueClient(config: QueueClientConfig): QueueClient;

declare class QueueProcessingError extends Error {
    readonly requeue: boolean;
    constructor(message: string, options?: {
        readonly requeue?: boolean;
        readonly cause?: unknown;
    });
}

export { QueueClient, type QueueClientConfig, QueueProcessingError, createQueueClient };
